class StateError(Exception):
    pass

class StateMachine:
    def __init__(self, initial_state: str):
        self.current_state = initial_state
        self.transitions = {}

    def add_transition(self, event: str, source: str, target: str, guard=None) -> None:
        self.transitions[(event, source)] = (target, guard)

    def trigger(self, event: str) -> str:
        key = (event, self.current_state)
        if key not in self.transitions:
            return self.current_state  # BUG: ignores invalid transition without raising StateError
        target, guard = self.transitions[key]
        if guard and not guard():
            raise StateError('Guard rejected')
        self.current_state = target
        return self.current_state

